import React, { useState, useEffect } from 'react';

const PomodoroTimer = () => {
  const [minutes, setMinutes] = useState(25);
  const [seconds, setSeconds] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const [mode, setMode] = useState('focus'); // 'focus' or 'break'
  const [isOpen, setIsOpen] = useState(false);

  useEffect(() => {
    let interval = null;
    if (isActive) {
      interval = setInterval(() => {
        if (seconds === 0) {
          if (minutes === 0) {
            setIsActive(false);
            const audio = new Audio('https://actions.google.com/sounds/v1/alarms/beep_short.ogg');
            audio.play().catch(() => {});
            if (mode === 'focus') {
                setMode('break');
                setMinutes(5);
            } else {
                setMode('focus');
                setMinutes(25);
            }
          } else {
            setMinutes(minutes - 1);
            setSeconds(59);
          }
        } else {
          setSeconds(seconds - 1);
        }
      }, 1000);
    } else {
      clearInterval(interval);
    }
    return () => clearInterval(interval);
  }, [isActive, minutes, seconds, mode]);

  const toggleTimer = () => setIsActive(!isActive);
  const resetTimer = () => {
    setIsActive(false);
    setMinutes(mode === 'focus' ? 25 : 5);
    setSeconds(0);
  };

  return (
    <div className="position-fixed" style={{ bottom: '80px', left: '20px', zIndex: 1040 }}>
      {isOpen && (
        <div className="card shadow-lg mb-2 slide-up text-center border-0" style={{ width: '200px', background: mode === 'focus' ? '#ff6b6b' : '#4ecdc4', color: 'white' }}>
          <div className="card-body p-3">
            <h6 className="mb-2">{mode === 'focus' ? '🔥 وقت التركيز' : '☕ استراحة'}</h6>
            <div className="display-4 fw-bold mb-3">
              {String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
            </div>
            <div className="d-flex justify-content-center gap-2">
              <button className="btn btn-sm btn-light text-dark fw-bold" onClick={toggleTimer}>{isActive ? 'إيقاف' : 'بدء'}</button>
              <button className="btn btn-sm btn-outline-light" onClick={resetTimer}>إعادة</button>
            </div>
          </div>
        </div>
      )}
      <button className="btn btn-danger rounded-circle shadow-lg d-flex align-items-center justify-content-center border-2 border-white" style={{ width: '50px', height: '50px' }} onClick={() => setIsOpen(!isOpen)} title="مؤقت المذاكرة">⏱️</button>
    </div>
  );
};

export default PomodoroTimer;
